'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
const {webcrypto}=require('node:crypto');
const Transfer=require(process.cwd()+'/js/sharedTransferChallenge.js');
const setup={phase:'SHOWDOWN_CONFIRMED',revision:6,coordinatorRole:'playerOne',totalSeasons:3,confirmedRoles:['playerOne','playerTwo'],clubs:{playerOne:'Arsenal',playerTwo:'Liverpool'}};
const careerStart={phase:'CAREER_START_READY',revision:2,acknowledgedRoles:['playerOne','playerTwo']};
(async()=>{
 const protocol=await Transfer.createProtocol({leagueIds:['england-premier-league','spain-primera-division'],nationalityIds:['spain','brazil'],cryptoImpl:webcrypto});
 let serial=0;
 for(const count of [0,1,2]){
  let state=null;
  const step=async(type,actorRole,extra={},now=1000000)=>{state=(await protocol.apply({state,setup,careerStart,seasonNumber:1,actorRole,nowEpochMs:now,command:{type,baseRevision:state?.revision||0,operationId:'transfer_op_'+(++serial).toString(16).padStart(32,'0'),...extra}})).state;};
  await step('start-window','playerOne');
  await step('request-end-window','playerOne');
  await step('request-end-window','playerTwo');
  const guesses=[{slot:1,type:'league',valueId:'spain-primera-division'},{slot:2,type:'nationality',valueId:'spain'}].slice(0,count);
  await step('lock-guesses','playerOne',{guesses});
  await step('lock-guesses','playerTwo',{guesses});
  assert.equal(state.phase,'SIGNING_ENTRY');
  await step('lock-signings','playerOne',{signings:[]});
  await step('lock-signings','playerTwo',{signings:[]});
  assert.equal(state.phase,'COMPLETED');
  console.log(JSON.stringify({guessesPerManager:count,phase:state.phase,lockedRoles:state.guessLockedRoles}));
 }
 const c={document:{getElementById:()=>null},console};c.window=c;vm.createContext(c);vm.runInContext(fs.readFileSync('js/transferChallenge.js','utf8'),c);
 const guesses=[{slot:1,type:'league',valueId:'spain-primera-division',value:'LaLiga'},{slot:2,type:'nationality',valueId:'spain',value:'Spain'}];
 const validation=c.getGuessValidationMessage({guesses:{againstPlayerOne:guesses,againstPlayerTwo:[...guesses,{slot:3,type:'nationality',valueId:'brazil',value:'Brazil'}]}});
 assert.equal(validation,'');
 const intro=c.getTransferPhaseIntro({status:'recording',phase:'guess_entry'});
 assert.match(intro,/up to three/);
 console.log(JSON.stringify({localGuessCounts:[2,3],validationMessage:validation,phaseIntro:intro}));
 const source=fs.readFileSync('js/productionSharedTransferChallenge.js','utf8');
 assert.match(source,/Lock \$\{filled\} of \$\{PSTC_MAX_ROWS\} \$\{noun\}\?/);
 assert.match(fs.readFileSync('tests/contracts/shared-transfer-challenge-contracts.cjs','utf8'),/const p2Guesses=\[[\s\S]*?slot:1[\s\S]*?slot:2[\s\S]*?\];/);
 console.log('PASS: fewer guesses are an explicit supported allowance, with a partial-lock confirmation and existing two-guess contract case. The findings assume an unestablished mandatory exactly-three rule.');
})().catch(e=>{console.error(e);process.exitCode=1;});
